import{I as e,P as t,Q as n,n as r}from"./chunks/framework.Bj5pAnfO.js";var i=JSON.parse(`{"title":"Adapting Your Harness","description":"","frontmatter":{"id":"guide.adapting-your-harness","title":"Adapting Your Harness"},"headers":[],"relativePath":"guides/adapting-your-harness.md","filePath":"guides/adapting-your-harness.md"}`),a={name:`guides/adapting-your-harness.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="adapting-your-harness" tabindex="-1">Adapting Your Harness <a class="header-anchor" href="#adapting-your-harness" aria-label="Permalink to “Adapting Your Harness”">​</a></h1><h2 id="how-do-i-wire-this-into-the-agent-i-actually-use" tabindex="-1">How do I wire this into the agent I actually use? <a class="header-anchor" href="#how-do-i-wire-this-into-the-agent-i-actually-use" aria-label="Permalink to “How do I wire this into the agent I actually use?”">​</a></h2><p>Workbench ships its infrastructure harness-neutral in <code>.agents/</code> and comes wired for <a href="https://omp.sh" target="_blank" rel="noreferrer">Oh My Pi</a>. Any other harness needs a deliberate one-time adaptation: point it at the contract and make its skills discoverable. Workbench wires no harness lifecycle events, so there is nothing else to adapt. Commit that configuration, then leave <code>.agents/</code> as the source of truth.</p><p>The checks that matter most do not depend on a harness noticing anything. The validator, continuous integration, and the commit hook run independently of the agent&#39;s instructions.</p><p>The <a href="./../PROCESS">current process</a> owns the workflow. Your checkout&#39;s <code>AGENTS.md</code> owns its agent instructions; <a href="https://github.com/markmals/workbench/blob/main/AGENTS.md" target="_blank" rel="noreferrer">Workbench&#39;s default-branch agent contract</a> is the template source. When reviewing an unmerged change, use the contract from that change&#39;s branch.</p><p>Ask your agent to make the harness-specific changes below. You should review and commit the result, then run a small feature through the process before relying on it for larger work.</p><h2 id="what-ships" tabindex="-1">What ships <a class="header-anchor" href="#what-ships" aria-label="Permalink to “What ships”">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What it contains</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>The agent contract — the one file every harness must load.</td></tr><tr><td><code>PROCESS.md</code></td><td>The full process description.</td></tr><tr><td><code>VISION.md</code></td><td>Your project&#39;s vision; replace Workbench&#39;s.</td></tr><tr><td><code>proposals/</code></td><td>One document per change, preserved as history.</td></tr><tr><td><code>policies/</code></td><td>Rules future work must keep enforcing.</td></tr><tr><td><code>decisions/</code></td><td>Architectural choices and the context that produced them.</td></tr><tr><td><code>guides/</code></td><td>User-facing documentation.</td></tr><tr><td><code>docs/</code></td><td>The site that publishes the vision, record, and guides.</td></tr><tr><td><code>tools/</code></td><td>The artifact validator and the small scripts the tasks run.</td></tr><tr><td><code>.agents/skills/</code></td><td>One skill directory per process phase or cross-cutting concern.</td></tr><tr><td><code>.agents/rules/</code></td><td>Code quality, commit discipline, and enforcement hierarchy.</td></tr><tr><td><code>.agents/templates/</code></td><td>The canonical shape of every artifact.</td></tr><tr><td><code>.agents/commit-scopes</code></td><td>The commit scopes the <code>commit-msg</code> hook accepts.</td></tr><tr><td><code>mise.toml</code></td><td>Every pinned tool and every task.</td></tr><tr><td><code>hk.pkl</code></td><td>Every git hook, including the Scoped Commits check.</td></tr><tr><td><code>.github/workflows/</code></td><td>Continuous integration and the preview workflow.</td></tr><tr><td><code>.omp/</code></td><td>Oh My Pi wiring: the <code>workflow</code> tool.</td></tr></tbody></table><p>When a harness needs its own configuration, generate it from <code>.agents/</code> rather than replacing the source. This prevents two copies of the process from becoming two different processes.</p><h2 id="if-you-use-oh-my-pi" tabindex="-1">If you use Oh My Pi <a class="header-anchor" href="#if-you-use-oh-my-pi" aria-label="Permalink to “If you use Oh My Pi”">​</a></h2><p>Nothing needs adapting. Oh My Pi loads <code>AGENTS.md</code> from the repository root and discovers <code>.agents/skills/</code> on its own, and <code>.omp/tools/dynamic-workflows/</code> registers the <code>workflow</code> tool.</p><p>Continue at <a href="#configure-the-readiness-report-account">Configure the readiness-report account</a>.</p><h2 id="point-the-harness-at-the-contract" tabindex="-1">Point the harness at the contract <a class="header-anchor" href="#point-the-harness-at-the-contract" aria-label="Permalink to “Point the harness at the contract”">​</a></h2><p>Most current harnesses load <code>AGENTS.md</code> from the repository root without configuration. If yours does, this step is complete.</p><p>If it expects another filename, add a thin file that defers to <code>AGENTS.md</code>; do not copy the contract. For Claude Code, create this shim at the repository root:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">printf</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> &#39;@AGENTS.md\\n&#39;</span><span style="--shiki-dark:#F97583;--shiki-light:#c62739;"> &gt;</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> CLAUDE.md</span></span></code></pre></div><p>If your harness has no import mechanism, create a symlink using the filename it expects:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">ln</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> -s</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> AGENTS.md</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> .harness-instructions.md</span></span></code></pre></div><p>The shim or symlink is harness configuration, not an alternative contract. Keep it small enough that a reader can see it delegates to <code>AGENTS.md</code>.</p><h2 id="make-skills-discoverable" tabindex="-1">Make skills discoverable <a class="header-anchor" href="#make-skills-discoverable" aria-label="Permalink to “Make skills discoverable”">​</a></h2><p>Each <code>.agents/skills/&lt;name&gt;/SKILL.md</code> has <code>name</code> and <code>description</code> frontmatter followed by its procedural instructions. The description is what an agent uses when deciding whether to load it.</p><p>If your harness discovers skills from a fixed directory, point that directory at <code>.agents/skills</code> with a symlink. Keep <code>.agents/skills</code> canonical; the harness-specific path is configuration, not a second copy.</p><p>A harness without a skill mechanism can still use Workbench. <code>AGENTS.md</code> names each skill at the point where it applies, so the agent can read it directly. Confirm that it follows those paths. If it cannot, put the two or three most important skill bodies in <code>AGENTS.md</code> rather than maintaining a parallel skills tree.</p><h2 id="git-hooks-need-no-adaptation" tabindex="-1">Git hooks need no adaptation <a class="header-anchor" href="#git-hooks-need-no-adaptation" aria-label="Permalink to “Git hooks need no adaptation”">​</a></h2><p>Git hooks are not harness wiring. <a href="https://hk.jdx.dev" target="_blank" rel="noreferrer">hk</a> owns them, <code>mise run setup</code> installs them with <code>hk install --mise</code>, and they run for every commit regardless of who or what made it — including the <code>commit-msg</code> step that holds every subject to Scoped Commits against the scopes in <code>.agents/commit-scopes</code>, the <code>pre-commit</code> step that formats staged files, and the steps that sync Beads on <code>git push</code> and <code>git pull</code>.</p><p>No hook runs the full gate. Continuous integration runs <code>mise run check</code> on every push and checks every commit in a pull request wherever it was made, and the agent waits for it before marking a pull request ready or merging. Orientation and formatting are commands the agent runs itself, <code>mise run status</code> and <code>mise run fmt -- &lt;files&gt;</code>, so a harness needs no event to trigger them.</p><h2 id="configure-the-readiness-report-account" tabindex="-1">Configure the readiness-report account <a class="header-anchor" href="#configure-the-readiness-report-account" aria-label="Permalink to “Configure the readiness-report account”">​</a></h2><p>The readiness report comes from a service account so the pull request distinguishes statements the agent made from statements you made.</p><p>Create a bot account or GitHub App, give it write access to the repository, and expose its token to the agent as <code>SERVICE_ACCOUNT_TOKEN</code>:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#F97583;--shiki-light:#c62739;">export</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;"> SERVICE_ACCOUNT_TOKEN</span><span style="--shiki-dark:#F97583;--shiki-light:#c62739;">=&lt;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">the bot</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&#39;s token&gt;</span></span></code></pre></div><p>The name matters. The agent sets <code>GH_TOKEN</code> from <code>SERVICE_ACCOUNT_TOKEN</code> only when posting its own readiness-report comment. Marking the pull request ready happens after the complete implementation is verified and pushed, with the ordinary <code>gh pr ready</code> identity. Exporting the service token as a global <code>GH_TOKEN</code> would attribute unrelated GitHub actions to the bot.</p><p>Without a service account the agent identifies the available account in the report, subject to your repository&#39;s identity rules.</p><h2 id="start-from-your-own-project-record" tabindex="-1">Start from your own project record <a class="header-anchor" href="#start-from-your-own-project-record" aria-label="Permalink to “Start from your own project record”">​</a></h2><p>Workbench includes its own record as an example. To replace it and write your project vision, follow <a href="./getting-started">Getting Started</a>. Keep <code>policies/</code> and <code>decisions/</code> empty until a feature actually establishes one; speculative policies are the ones nobody follows.</p><p>A preview must be the cheapest realistic artifact through which a human can exercise a change. To choose and wire the one for your repository shape, see <a href="./choosing-a-preview">Choosing a Preview</a>.</p><h2 id="verify-the-adoption" tabindex="-1">Verify the adoption <a class="header-anchor" href="#verify-the-adoption" aria-label="Permalink to “Verify the adoption”">​</a></h2><p>Provision the toolchain, bootstrap the repository, and run the full gate:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> setup</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> check</span></span></code></pre></div><p>Then run one small feature end to end: branch, draft pull request, proposal, current specification, tests, guides, code, review, and readiness report. The first pass exposes what your harness does not do well while the change is still cheap to correct.</p><h2 id="add-another-harness-without-forking" tabindex="-1">Add another harness without forking <a class="header-anchor" href="#add-another-harness-without-forking" aria-label="Permalink to “Add another harness without forking”">​</a></h2><p>Repeat the contract and skill steps for the new harness. Do not fork <code>.agents/</code>; derive the new harness configuration from it.</p><p>If two harnesses need genuinely different instructions, make that difference an explicit note in <code>AGENTS.md</code>. Do not leave two divergent copies of the contract or skills for future maintainers to reconcile.</p><p>For the feature lifecycle the harness supports, see <a href="./running-a-feature">Running a Feature</a>.</p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};